import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import test from 'node:test';
function setup(){const app={innerHTML:''},dialog={close(){},showModal(){}},ctx=vm.createContext({console,structuredClone,URL,AbortController,setTimeout,clearTimeout,document:{querySelector(k){return k==='#app'?app:k==='#dialog'?dialog:k==='.main'?{scrollTo(){}}:null},addEventListener(){}},localStorage:{getItem:()=>null,setItem(){}}});ctx.window=ctx;ctx.addEventListener=()=>{};for(const f of ['model.js','menu-renderer.js','menu-layouts.js','reference-design.js','brand-materials.js','studio.js','reference-controller.js','simple-flow.js','codex-client.js'])vm.runInContext(readFileSync(new URL(f,import.meta.url),'utf8'),ctx);vm.runInContext('toast=()=>{};home=false',ctx);return {ctx,app,dialog};}
const design={styleName:'测试',summary:'布局测试',composition:'双栏',typography:'无衬线',decoration:'简洁',recipe:'editorial',capacity:2,palette:{bg:'#FFFFFF',ink:'#222222',accent:'#990000',card:'#EEEEEE',muted:'#777777',line:'#CCCCCC'},slots:[{x:0,y:0,w:.45,h:.9},{x:.55,y:.05,w:.45,h:.9}]};
test('consent precedes network access, payload omits product facts',async()=>{const {ctx,dialog}=setup();let calls=0;ctx.fetch=()=>{calls++;throw Error('unexpected')};await vm.runInContext("act('simple-generate','')",ctx);assert.match(dialog.innerHTML,/同意发送并开始/);assert.equal(calls,0);const p=JSON.parse(vm.runInContext("aiPayload('generate').brief",ctx));assert.equal(p.products[0].name,undefined);assert.equal(p.products[0].price,undefined);await vm.runInContext("act('ai-dismiss','')",ctx);assert.equal(calls,0);});
test('historical simulated analysis cannot unlock uploaded image',()=>{const {ctx}=setup();vm.runInContext("Object.assign(Ref.ensure(s),{source:'upload',analysis:{status:'ready',kind:'demo'}})",ctx);assert.equal(vm.runInContext('simpleTemplateReady()',ctx),false);});
test('real response drives geometry, capacity and editable result',async()=>{const {ctx}=setup();vm.runInContext("s.step=3;s.items[5].price=36;Ref.choose(s,'collage');Ref.finishAnalysis(s);s.compositionVariant=1",ctx);ctx.fetch=async url=>({ok:true,json:async()=>url.endsWith('/status')?{token:'test'}:{result:structuredClone(design),completedAt:'2026-09-30T00:00:00Z'}});await vm.runInContext("act('simple-generate','');act('ai-start','')",ctx);assert.equal(vm.runInContext('s.generated',ctx),true);assert.equal(vm.runInContext('s.step',ctx),7);assert.equal(vm.runInContext('s.fontMood',ctx),'sans');assert.equal(vm.runInContext('s.compositionVariant',ctx),0);vm.runInContext('simpleSetCapacity()',ctx);assert.equal(vm.runInContext('s.density',ctx),2);assert.equal(vm.runInContext('M.pages(s).length',ctx),6);assert.equal(vm.runInContext('R.positions(s,M.pages(s)[0])[0].x',ctx),50);await vm.runInContext("act('editor-style','clean')",ctx);assert.equal(vm.runInContext('s.aiDesign.palette===R.palettes.clean',ctx),true);});
test('failed real request reports failure without simulated success',async()=>{const {ctx}=setup();ctx.fetch=async()=>{throw Error('Failed to fetch')};vm.runInContext("s.step=5;Object.assign(Ref.ensure(s),{source:'upload',image:'data:image/png;base64,demo',analysis:{status:'idle'}})",ctx);await vm.runInContext("act('ref-analyze','');act('ai-start','')",ctx);assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'failed');assert.equal(vm.runInContext('simpleTemplateReady()',ctx),false);assert.match(vm.runInContext('error',ctx),/无法连接/);});
